// P1-S06A: local disposable reference only. Never accepts a hosted database.
import pg from "pg";
import { randomBytes } from "node:crypto";
import { spawnSync } from "node:child_process";
import {
  cpSync,
  mkdtempSync,
  mkdirSync,
  readdirSync,
  writeFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { databaseSettings } from "../../src/lib/profile";

// Never force-terminate a pool that is still completing its asynchronous close.
// Only names generated by these local control/profile rehearsals are eligible.
export async function dropDisposableLedgerDatabase(
  admin: pg.Client,
  name: string,
) {
  if (
    !/^ledgerone_(controls_[a-f0-9]{16}|profile_[a-f0-9]{12})_test$/.test(name)
  )
    throw new Error("Refusing non-disposable database cleanup");
  const deadline = Date.now() + 5000;
  while (true) {
    const state = await admin.query<{ count: number }>(
      "SELECT count(*)::int AS count FROM pg_stat_activity WHERE datname=$1",
      [name],
    );
    if (state.rows[0]?.count === 0) break;
    if (Date.now() >= deadline)
      throw new Error(
        "Disposable database still has open connections; force deletion refused",
      );
    await new Promise((resolve) => setTimeout(resolve, 25));
  }
  // If another connection races the check, DROP fails safely rather than killing it.
  await admin.query(`DROP DATABASE "${name}"`);
}
export async function createFreshLedgerDatabase(source: string) {
  return createLocalLedgerDatabase(source, "public");
}
// Separate local-only composition; the original public factory stays strict.
export async function createLocalPrivateLedgerDatabase(
  source: string,
  upgrade = false,
) {
  return createLocalLedgerDatabase(source, "ledgerone", upgrade);
}
export async function createLegacyOpeningDatabase(source: string) {
  return createLocalLedgerDatabase(source, "public", true, true);
}
async function createLocalLedgerDatabase(
  source: string,
  schema: "public" | "ledgerone",
  upgrade = false,
  legacyOnly = false,
) {
  databaseSettings({ LEDGERONE_ENV: "test", DATABASE_URL: source });
  const input = new URL(source);
  if (
    !["127.0.0.1", "localhost", "[::1]"].includes(input.hostname) ||
    !input.pathname.endsWith("_test") ||
    (input.searchParams.get("schema") &&
      input.searchParams.get("schema") !== "public")
  )
    throw new Error(
      "A loopback public-schema *_test reference source is required",
    );
  const name = `ledgerone_controls_${randomBytes(8).toString("hex")}_test`;
  async function cleanup() {
    const admin = new pg.Client({ connectionString: source });
    try {
      await admin.connect();
      await dropDisposableLedgerDatabase(admin, name);
    } finally {
      await admin.end();
    }
  }
  const admin = new pg.Client({ connectionString: source });
  let created = false;
  try {
    try {
      await admin.connect();
      await admin.query(`CREATE DATABASE "${name}"`);
      created = true;
    } finally {
      await admin.end();
    }
    const target = new URL(input);
    target.pathname = `/${name}`;
    target.searchParams.set("schema", schema);
    if (schema === "ledgerone") {
      const provision = new pg.Client({ connectionString: target.toString() });
      try {
        await provision.connect();
        await provision.query('CREATE SCHEMA "ledgerone"');
      } finally {
        await provision.end();
      }
    }
    const environment = {
      ...process.env,
      LEDGERONE_ENV: "test",
      DATABASE_URL: target.toString(),
      DIRECT_DATABASE_URL: target.toString(),
      TEST_DATABASE_URL: target.toString(),
    };
    let upgradeFrom: string | null = null;
    if (upgrade) {
      const directory = mkdtempSync(
        join(tmpdir(), "ledgerone-private-upgrade-"),
      );
      try {
        const migrations = join(directory, "migrations");
        mkdirSync(migrations);
        cpSync(
          "prisma/migrations/migration_lock.toml",
          join(migrations, "migration_lock.toml"),
        );
        const names = readdirSync("prisma/migrations")
          .filter((n) =>
            (legacyOnly ? /^20261111000[1-7]_/ : /^20261111000[1-6]_/).test(n),
          )
          .sort();
        if (names.length !== (legacyOnly ? 7 : 6))
          throw new Error("Unexpected predecessor migration set");
        for (const name of names)
          cpSync(join("prisma/migrations", name), join(migrations, name), {
            recursive: true,
          });
        const config = join(directory, "prisma.config.ts");
        writeFileSync(
          config,
          `import {defineConfig} from ${JSON.stringify(resolve("node_modules/prisma/config.js"))};\nexport default defineConfig({schema:${JSON.stringify(resolve("prisma/schema.prisma"))},migrations:{path:${JSON.stringify(migrations)}},datasource:{url:process.env.DATABASE_URL}});\n`,
          { mode: 0o600 },
        );
        const predecessor = spawnSync(
          process.execPath,
          [
            "node_modules/prisma/build/index.js",
            "migrate",
            "deploy",
            "--config",
            config,
          ],
          { encoding: "utf8", env: environment },
        );
        if (predecessor.status !== 0)
          throw new Error(
            "Private predecessor migration failed (output withheld)",
          );
        const inspector = new pg.Client({
          connectionString: target.toString(),
        });
        try {
          await inspector.connect();
          const version = await inspector.query(
            `SELECT value FROM "${schema}".app_metadata WHERE key='schema_version'`,
          );
          const history = await inspector.query(
            `SELECT count(*)::int AS count FROM "${schema}"._prisma_migrations WHERE finished_at IS NOT NULL`,
          );
          if (
            version.rows[0]?.value !== (legacyOnly ? "7" : "6") ||
            history.rows[0]?.count !== (legacyOnly ? 7 : 6)
          )
            throw new Error("Private predecessor history mismatch");
          upgradeFrom = legacyOnly ? "7" : "6";
        } finally {
          await inspector.end();
        }
      } finally {
        rmSync(directory, { recursive: true, force: true });
      }
    }
    if (legacyOnly) return { url: target.toString(), cleanup, upgradeFrom };
    const result = spawnSync(
      process.execPath,
      ["node_modules/prisma/build/index.js", "migrate", "deploy"],
      {
        encoding: "utf8",
        env: environment,
      },
    );
    if (result.status !== 0)
      throw new Error(
        "Fresh reference migration failed (output withheld to protect credentials)",
      );
    return { url: target.toString(), cleanup, upgradeFrom };
  } catch (error) {
    if (created) await cleanup();
    throw error;
  }
}
export async function withFreshLedgerDatabase<T>(
  source: string,
  work: (url: string) => Promise<T>,
) {
  const lease = await createFreshLedgerDatabase(source);
  try {
    return await work(lease.url);
  } finally {
    await lease.cleanup();
  }
}
